import json, time, urllib.request, urllib.error, collections, sys
BASE = "http://localhost:8080"
tok = None
log = collections.Counter()
def get_token():
    global tok
    while True:
        try:
            r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST"), timeout=30)
            tok = json.load(r)["token"]; log["token"] += 1; return
        except urllib.error.HTTPError as e:
            log[f"token_{e.code}"] += 1; handle_wait(e)
def handle_wait(e):
    ra = e.headers.get("Retry-After")
    body = e.read().decode(errors="replace")
    if ra is None:
        try: ra = json.loads(body).get("retry_after")
        except Exception: pass
    if e.code not in (401, 404): log.setdefault("samples", []) if False else None
    sample[e.code] = (dict(e.headers), body[:300])
    time.sleep(float(ra) if ra else 1.0)
sample = {}
def get(path):
    if tok is None: get_token()
    while True:
        req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {tok}"})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            body = r.read()
            try: return json.loads(body)
            except Exception:
                log["badjson"] += 1; sample["badjson"] = body[:300]; time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            log[f"http_{e.code}"] += 1
            if e.code == 401:
                sample[401] = (dict(e.headers), e.read().decode()[:300]); get_token(); continue
            if e.code == 404: sample[404] = e.read().decode()[:300]; return None
            handle_wait(e)
        except Exception as e:
            log["exc"] += 1; sample["exc"] = repr(e); time.sleep(1)
pages = {}
p = 1; total = None
while True:
    d = get(f"/orders?page={p}")
    if d is None: print("404 page", p); break
    if d.get("page") != p: log["page_mismatch"] += 1
    pages[p] = d; total = d["total_pages"]
    print("page", p, len(d["items"]), d["next"], file=sys.stderr)
    if p >= total and d["next"] is None: break
    if d["next"] is None: log["next_null_early"] += 1
    p += 1
json.dump(pages, open("/tmp/recon/pages.json", "w"))
custs = {}
ids = sorted({o["customer_id"] for d in pages.values() for o in d["items"]})
for c in ids:
    custs[c] = get(f"/customers/{c}")
json.dump(custs, open("/tmp/recon/customers.json", "w"))
print(dict(log)); print(json.dumps({str(k): v for k, v in sample.items()}, default=str, indent=1))
EOF
python3 -I /tmp/recon/fetch.py 2>/tmp/recon/progress.log | tail -50; tail -5 /tmp/recon/progress.log

